// Build team id->name map and store in static data.
// Returns the first-page fetch parameters {offset, limit}.
function ensureObj(x) {
  if (!x) return {};
  if (typeof x === 'string') { try { return JSON.parse(x); } catch { return {}; } }
  return x;
}
const resp  = ensureObj($json);
const teams = resp.teams || resp.data || [];
const idToName = {};
const nameToId = {};
for (const t of teams) {
  if (!t || !t.id) continue;
  const name = (t.name || '').trim();
  idToName[t.id] = name;
  if (name) nameToId[name.toLowerCase()] = t.id;
}
const sd = $getWorkflowStaticData('global');
sd.teamIdToName = idToName;
sd.teamNameToId = nameToId;
sd.bfOffset     = 0;  // reset on every fresh run
console.log(`[Backfill] Team map: ${Object.keys(idToName).length} teams. Starting offset=0.`);
// Output the first page parameters — used by Fetch Tickets node via $json.offset / $json.limit
return [{ json: { offset: 0, limit: 150 } }];

// PAGINATE — runs ONCE for the whole page (default mode, NOT runOnceForEachItem).
// KEY: we ALWAYS return offset=0 because each cycle's PATCHes remove those rows from
// the Supabase filter result. Incrementing the offset would SKIP rows as the result
// set shrinks — that was the bug causing only 1350/3000 rows to be processed.
// We stop when a page returns fewer than PAGE_SIZE rows.
const items     = $input.all();
const PAGE_SIZE = 150;
const hasMore   = items.length >= PAGE_SIZE;
console.log(`[Backfill] Page: ${items.length} items | hasMore:${hasMore} | offset always 0`);
return [{ json: { has_next: hasMore, offset: 0, limit: PAGE_SIZE } }];

// TRANSFORM – identical logic to the main All Team Ticket Log workflow
const TRACKED_TEAMS=['Pro Solutions Task Force','CEx Reversal','Ticket Dependencies','Payments and Treasury','GB Email Communication','Tech Team','Business Operations','Platform Operations','Case Resolution'];
function getTeamCode(t){const tn=(t||'').toLowerCase();if(tn.includes('pro solutions')||tn.includes('cex reversal')||tn.includes('ticket dependencies'))return 'CEx';if(tn.includes('business operations'))return 'BO';if(tn.includes('payments')||tn.includes('treasury')||tn.includes('gb email'))return 'PT';if(tn.includes('platform operations'))return 'PO';if(tn.includes('tech team'))return 'TT';if(tn.includes('case resolution'))return 'CR';return '';}
const TWH={'CEx':{start:0,end:24},'PT':{start:9,end:18},'TT':{start:9,end:18},'PO':{start:8.5,end:17.5},'CR':{start:8.5,end:17.5},'BO':{start:8.5,end:17.5}};
const SLA={'CEx':{weekdayOffice:1,weekdayAfter:1,weekendOffice:1,weekendAfter:1},'BO':{weekdayOffice:12,weekdayAfter:24,weekendOffice:12,weekendAfter:24},'PT':{weekdayOffice:12,weekdayAfter:12,weekendOffice:24,weekendAfter:24},'PO':{weekdayOffice:3,weekdayAfter:18,weekendOffice:24,weekendAfter:24},'TT':{weekdayOffice:8,weekdayAfter:20,weekendOffice:72,weekendAfter:72},'CR':{weekdayOffice:3,weekdayAfter:17,weekendOffice:54,weekendAfter:54}};
function sH(h){if(!h)return '';return String(h).replace(/<br\s*\/?>/gi,'\n').replace(/<\/p>/gi,'\n').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim();}
function toISO(n){n=typeof n==='number'?n:parseInt(n,10);if(!n||isNaN(n))return '';return new Date((n+21600)*1000).toISOString().slice(0,10);}
function norm(s){return(s||'').toString().trim().toLowerCase();}
function gA(p){const a=p?.author||p?.created_by||p?.creator||{};return{id:a?.id?String(a.id):'',name:a?.name||'',email:a?.email||'',type:a?.type||''};}
function fmt(s){if(!s||s<0)return '';const d=Math.floor(s/86400),h=Math.floor((s%86400)/3600),m=Math.floor((s%3600)/60);let r='';if(d>0)r+=d+'d ';if(h>0)r+=h+'h ';if(m>0||r==='')r+=m+'m';return r.trim();}
function inWH(ts,tc){if(!ts||!tc)return true;const hrs=TWH[tc];if(!hrs)return true;const dt=new Date((ts+21600)*1000);const h=dt.getUTCHours()+dt.getUTCMinutes()/60;return h>=hrs.start&&h<hrs.end;}
function isWE(ts){if(!ts)return false;return[0,6].includes(new Date((ts+21600)*1000).getUTCDay());}
function gSla(tc,we,off){const l=SLA[tc];if(!l)return 24;return we?(off?l.weekendOffice:l.weekendAfter):(off?l.weekdayOffice:l.weekdayAfter);}
const ticket=$json||{};
if(ticket.type==='error.list'||ticket.errors){console.log('[Backfill] Intercom error – skipping');return{json:{_skip:true}};}
const iId=String(ticket.id||'');
const tId=String(ticket.ticket_id||ticket.id||'');
const tState=norm(ticket.ticket_state||ticket.state||'');
const tLabel=ticket.ticket_state_internal_label||ticket.ticket_state_external_label||ticket.ticket_state||'';
const isRes=(tState==='resolved'||tState==='closed');
let pt='';const ta=ticket.ticket_attributes||{};
for(const k of Object.keys(ta)){if(k.toLowerCase().includes('product')&&k.toLowerCase().includes('type')){pt=String(ta[k]||'');break;}}
if(!pt&&ta['Product Type'])pt=String(ta['Product Type']);
const ptl=pt.toLowerCase();if(ptl==='cfds'||ptl==='cfd')pt='CFD';else if(ptl==='futures')pt='Futures';else if(ptl.includes('stellar')||ptl.includes('instant'))pt='CFD';
let ic='';if(ticket.ticket_type?.name)ic=ticket.ticket_type.name;else if(ticket.custom_attributes?.ticket_type)ic=ticket.custom_attributes.ticket_type;
if(!ic)ic=sH(ticket?.ticket_attributes?._default_title_||ticket?.title||ticket?.subject||'');
const cArr=ticket?.contacts?.contacts||(Array.isArray(ticket?.contacts)?ticket.contacts:[]);
const con=cArr[0]||{};
let parts=ticket.ticket_parts||[];if(!Array.isArray(parts)){const tp=ticket.ticket_parts||{};parts=Array.isArray(tp.ticket_parts)?tp.ticket_parts:(Array.isArray(tp.data)?tp.data:[]);}
parts.sort((a,b)=>(a?.created_at||0)-(b?.created_at||0));
const tCA=ticket.created_at||0;
let rAt=0,rFCE='';
if(isRes&&ticket.state_updated_at>0)rAt=ticket.state_updated_at;
if(!rAt){for(const p of parts){const cs=norm(p?.ticket_state||p?.ticket_state_internal_label||'');const pca=p.created_at||0;if((cs.includes('resolved')||cs.includes('closed'))&&pca>rAt){rAt=pca;const au=gA(p);if(au.type==='admin'&&au.name)rFCE=au.name;}}}
if(!rAt&&isRes)rAt=tCA;
if(rAt>1e11)rAt=Math.floor(rAt/1000);
const rSec=(rAt&&tCA&&rAt>tCA)?(rAt-tCA):0;
const rTime=fmt(rSec);const rDate=toISO(rAt);
const fAP=parts.find(p=>gA(p).type==='admin');
const crN=fAP?gA(fAP).name:(con?.name||'');
const crE=fAP?gA(fAP).email:(con?.email||'');
const tv=new Set();let aAT=[],lN='',lA='';
const sd=$getWorkflowStaticData('global');
const tin=sd.teamIdToName||{};
const cTN=tin[String(ticket.team_assignee_id||'')]||'';
if(cTN)tv.add(cTN);
for(const p of parts){
  const au=gA(p);const body=sH(p?.body||p?.comment||p?.note||'');
  const ptype=norm(p?.part_type||p?.event_type||p?.type||'');const pca=p.created_at||0;
  if(norm(au.type)==='admin'&&body)lN=body;
  const at=p.assigned_to||p.assignee||{};
  if(at.type==='team'){const tn=at.name||tin[String(at.id||'')]||'';if(tn)tv.add(tn);}
  if(ptype.includes('assign')||ptype==='team_assignment'){if(pca>0)aAT.push(pca);if(at.type==='admin'&&at.name)lA=at.name;}
}
const hN=rFCE||lA||'';
let aHT='',aHTSec=0;
if(rAt){const va=aAT.filter(t=>t>0&&t<=rAt).sort((a,b)=>b-a);aHTSec=va.length>0?(rAt-va[0]):(rAt-tCA);aHT=fmt(aHTSec);}
const utc=tv.size;const isPSTF=(utc===2&&tv.has('Pro Solutions Task Force')&&tv.has('CEx Reversal'));
const slaA=utc<=1||isPSTF;
let slaHrs=24;const tc=getTeamCode(cTN);
if(tc==='CEx')slaHrs=1;else if(tc)slaHrs=gSla(tc,isWE(tCA),inWH(tCA,tc));
const slaSec=slaHrs*3600;
let tSla='N/A';if(slaA&&rSec>0)tSla=rSec<=slaSec?'Met':'Missed';
let aSla='N/A';if(aHTSec>0)aSla=aHTSec<=slaSec?'Met':'Missed';
const rdoh=(rAt&&tc)?inWH(rAt,tc):null;
const teamCols={};
for(const tn of TRACKED_TEAMS)teamCols[tn]=tv.has(tn)?'Yes':'';
const uId=`${rDate||toISO(tCA)}|${tId}`;
console.log(`[Backfill] ticket=${tId} team=${cTN} handler=${hN}`);
return{json:{_skip:false,unique_id:uId,ticket_id:tId,intercom_id:iId,ticket_creator_agent_name:crN,ticket_handler_agent_name:hN,resolution_time:rTime,agent_handle_time:aHT,ticket_status:tLabel,sla:tSla,sla_limit_hours:slaHrs,product_type:pt,resolved_during_office_hours:rdoh,current_team:cTN,issue_category:ic,description_last_ticket_note:lN,ticket_creator_email:crE,pro_solutions_task_force:teamCols['Pro Solutions Task Force'],cex_reversal:teamCols['CEx Reversal'],ticket_dependencies:teamCols['Ticket Dependencies'],payments_and_treasury:teamCols['Payments and Treasury'],gb_email_communication:teamCols['GB Email Communication'],tech_team:teamCols['Tech Team'],business_operations:teamCols['Business Operations'],platform_operations:teamCols['Platform Operations'],case_resolution:teamCols['Case Resolution'],ticket_sla_status:tSla,ticket_sla_limit_hours:slaHrs,ticket_sla_duration_seconds:rSec,agent_sla_status:aSla,agent_handle_time_seconds:aHTSec}};
